/** One immutable Source-owned lossless C representation, not an archive importer. */
import assert from'node:assert/strict';import{createHash}from'node:crypto';import{gunzipSync}from'node:zlib';
const sha=b=>createHash('sha256').update(b).digest('hex');
const encoded="";
assert.equal(encoded.length,6056476);const packed=Buffer.from(encoded,'base64');assert.equal(packed.toString('base64'),encoded);assert.equal(packed.length,4542357);assert.equal(sha(packed),"4a8b7bb9c18763a6e5a6d4cd930197264a5eb9afab48fbc2817545e4bc32909b");
const decoded=gunzipSync(packed,{maxOutputLength:17905017});assert.equal(decoded.length,17905017);assert.equal(sha(decoded),"650872f6003f2f930541a58601afe169d844564bc7836bdb01ec245eacf29883");const text=new TextDecoder('utf-8',{fatal:true}).decode(decoded);assert.equal(Buffer.byteLength(text),17905017);
const freeze=x=>{if(x&&typeof x==='object'){for(const y of Object.values(x))freeze(y);Object.freeze(x);}return x;};
export const PACKING189_CONTRACT=freeze(JSON.parse(text));
